// Drives the real login flows of a local Keycloak (dev/kc-up.sh) and captures screenshots of every styled page.
//
//   node dev/flows/run-flows.mjs                 all combinations
//   FLOWS_LOCALES=en FLOWS_SCHEMES=dark FLOWS_VIEWPORTS=390 node dev/flows/run-flows.mjs   narrow down
//
// Output: docs/design/screenshots/keycloak-<page>-<locale>-<scheme>-<width>.png (gitignored).
// Dev tool only (not part of CI). Playwright comes from tests/e2e/node_modules. Throwaway passwords are read from
// dev/.runtime/secrets.env (generated by kc-up.sh); they are never printed. Only talks to http://localhost:8085.
import { chromium } from '../../../../tests/e2e/node_modules/playwright/index.mjs';
import { createHash, createHmac, randomBytes } from 'node:crypto';
import { readFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const secrets = Object.fromEntries(
  readFileSync(here('../.runtime/secrets.env'), 'utf8')
    .split('\n')
    .filter((l) => l.includes('='))
    .map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1).trim()]),
);
const KC = 'http://localhost:8085';
const REALM = 'babyroutine-dev';
const OUT = process.env.FLOWS_OUT ?? here('../../../../docs/design/screenshots');
mkdirSync(OUT, { recursive: true });

const LOCALES = (process.env.FLOWS_LOCALES ?? 'en,pt-BR').split(',');
const SCHEMES = (process.env.FLOWS_SCHEMES ?? 'dark,light').split(',');
const VIEWPORTS = (process.env.FLOWS_VIEWPORTS ?? '390,1280').split(',').map(Number);
const SIZE = { 390: { width: 390, height: 844 }, 1280: { width: 1280, height: 800 } };

// ---------- admin helpers ----------
async function adminToken() {
  const res = await fetch(`${KC}/realms/master/protocol/openid-connect/token`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'password', client_id: 'admin-cli', username: 'admin', password: secrets.KC_ADMIN_PASSWORD }),
  });
  return (await res.json()).access_token;
}
async function admin(method, path, body) {
  const res = await fetch(`${KC}/admin/realms/${REALM}${path}`, {
    method,
    headers: { authorization: `Bearer ${await adminToken()}`, 'content-type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok && res.status !== 404) throw new Error(`${method} ${path} -> ${res.status}`);
  return res;
}
const created = [];
async function newUser(tag, { requiredActions = [], emailVerified = true } = {}) {
  const username = `${tag}${randomBytes(3).toString('hex')}`;
  const res = await admin('POST', '/users', {
    username,
    email: `${username}@example.test`,
    firstName: 'Ana',
    lastName: 'Silva',
    enabled: true,
    emailVerified,
    requiredActions,
    credentials: [{ type: 'password', value: secrets.KC_USER_PASSWORD, temporary: false }],
  });
  const id = res.headers.get('location').split('/').pop();
  created.push(id);
  return username;
}

// ---------- TOTP ----------
function base32decode(s) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  for (const c of s.replace(/[\s=]/g, '').toUpperCase()) bits += alphabet.indexOf(c).toString(2).padStart(5, '0');
  return Buffer.from(bits.match(/.{8}/g).map((b) => parseInt(b, 2)));
}
function totp(secret) {
  const counter = Buffer.alloc(8);
  counter.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000)));
  const h = createHmac('sha1', base32decode(secret)).update(counter).digest();
  const o = h[19] & 0xf;
  return String(((h.readUInt32BE(o) & 0x7fffffff) % 1_000_000)).padStart(6, '0');
}

// ---------- flow ----------
function authUrl(locale, extra = {}) {
  const verifier = randomBytes(32).toString('base64url');
  const params = new URLSearchParams({
    client_id: 'baby-routine-web',
    redirect_uri: 'http://localhost:5190/cb',
    response_type: 'code',
    scope: 'openid',
    state: 'x',
    code_challenge: createHash('sha256').update(verifier).digest('base64url'),
    code_challenge_method: 'S256',
    kc_locale: locale,
    ...extra,
  });
  return `${KC}/realms/${REALM}/protocol/openid-connect/auth?${params}`;
}

async function runCombo(browser, locale, scheme, width) {
  const ctx = await browser.newContext({ viewport: SIZE[width], colorScheme: scheme, locale: locale === 'pt-BR' ? 'pt-BR' : 'en-US' });
  await ctx.route('http://localhost:5190/**', (r) => r.fulfill({ contentType: 'text/html', body: '<p>redirected</p>' }));
  const page = await ctx.newPage();
  const shot = async (name) => {
    await page.waitForLoadState('networkidle');
    await page.waitForTimeout(250);
    await page.screenshot({ path: `${OUT}/keycloak-${name}-${locale}-${scheme}-${width}.png`, fullPage: true });
    console.log(`  ${name}`);
  };
  const pw = secrets.KC_USER_PASSWORD;
  const fillLogin = async (user, password = pw) => {
    await page.fill('#username', user);
    await page.fill('#password', password);
    await page.click('#kc-login');
  };
  const start = async (extra) => {
    await page.goto(authUrl(locale, extra));
    await page.waitForSelector('.br-card');
  };

  // login, wrong password
  const ana = await newUser('ana');
  await start();
  await shot('login');
  await fillLogin(ana, 'wrong-password');
  await page.waitForSelector('#input-error, .br-alert');
  await shot('login-error');

  // password visibility toggle (revealed state)
  await page.fill('#password', 'visible-demo');
  await page.click('.br-eye');
  await shot('login-password-revealed');

  // login page expired (stale session code)
  await start();
  await page.evaluate(() => {
    const f = document.querySelector('#kc-form-login');
    f.action = f.action.replace(/session_code=[^&]+/, 'session_code=stale');
  });
  await fillLogin(ana);
  await page.waitForLoadState('networkidle');
  await shot('page-expired');

  // register with validation errors, then reset password
  await start();
  await page.click('#kc-registration a');
  await page.waitForSelector('#email');
  await shot('register');
  await page.fill('#username', ana); // taken
  await page.fill('#email', 'not-an-email');
  await page.fill('#firstName', 'Ana');
  await page.fill('#lastName', 'Silva');
  if (await page.locator('#password').count()) {
    await page.fill('#password', 'abc');
    await page.fill('#password-confirm', 'abd');
  }
  await page.keyboard.press('Tab');
  await page.waitForTimeout(200);
  const submit = page.locator('#kc-form-buttons input[type=submit], #kc-form-buttons button[type=submit]');
  if (await submit.isEnabled()) await submit.click();
  await shot('register-errors');

  await start();
  await page.click('a[href*="reset-credentials"]');
  await page.waitForSelector('#username');
  await shot('reset-password');
  await page.fill('#username', ana);
  await page.click('input[type=submit], button[type=submit]');
  await page.waitForLoadState('networkidle');
  await shot('reset-password-sent');

  // new user through registration -> verify email notice
  await start();
  await page.click('#kc-registration a');
  const fresh = `new${randomBytes(3).toString('hex')}`;
  await page.fill('#username', fresh);
  await page.fill('#email', `${fresh}@example.test`);
  await page.fill('#firstName', 'Bia');
  await page.fill('#lastName', 'Costa');
  if (await page.locator('#password').count()) {
    await page.fill('#password', pw);
    await page.fill('#password-confirm', pw);
  }
  await page.click('#kc-form-buttons input[type=submit], #kc-form-buttons button[type=submit]');
  await page.waitForLoadState('networkidle');
  await shot('after-register');
  if (await page.locator('#password-new').count()) {
    await page.fill('#password-new', pw);
    await page.fill('#password-confirm', pw);
    await page.click('input[type=submit]');
    await page.waitForLoadState('networkidle');
  }
  await shot('verify-email');
  const users = await (await admin('GET', `/users?username=${fresh}&exact=true`)).json();
  if (users[0]) created.push(users[0].id);

  // required actions: update password (with mismatch error), update profile, terms
  const nina = await newUser('nina', { requiredActions: ['UPDATE_PASSWORD'] });
  await start();
  await fillLogin(nina);
  await page.waitForSelector('#password-new');
  await shot('update-password');
  await page.fill('#password-new', 'Another-pass-1');
  await page.fill('#password-confirm', 'different-one');
  await page.click('input[type=submit]');
  await page.waitForLoadState('networkidle');
  await shot('update-password-error');

  const uma = await newUser('uma', { requiredActions: ['UPDATE_PROFILE'] });
  await start();
  await fillLogin(uma);
  await page.waitForSelector('#firstName');
  await shot('update-profile');

  const tess = await newUser('tess', { requiredActions: ['TERMS_AND_CONDITIONS'] });
  await start();
  await fillLogin(tess);
  await page.waitForSelector('#kc-accept');
  await shot('terms');

  // OTP: setup (wrong code error), complete with a computed code, then sign in again for the OTP prompt
  const otto = await newUser('otto', { requiredActions: ['CONFIGURE_TOTP'] });
  await start();
  await fillLogin(otto);
  await page.waitForSelector('#kc-totp-settings');
  await shot('totp-setup');
  await page.fill('#totp', '000000');
  await page.fill('#userLabel', 'Phone').catch(() => {});
  await page.click('#saveTOTPBtn');
  await page.waitForLoadState('networkidle');
  await shot('totp-setup-error');
  const manual = page.locator('#mode-manual, a[href*="mode=manual"]').first();
  if (await manual.count()) await manual.click();
  await page.waitForSelector('#kc-totp-secret-key');
  const secret = (await page.textContent('#kc-totp-secret-key')).trim();
  await page.fill('#totp', totp(secret));
  await page.fill('#userLabel', 'Phone').catch(() => {});
  await page.click('#saveTOTPBtn');
  await page.waitForLoadState('networkidle');
  await ctx.clearCookies();
  await start();
  await fillLogin(otto);
  await page.waitForSelector('#otp');
  await shot('otp');
  await page.fill('#otp', '000000');
  await page.click('#kc-login');
  await page.waitForLoadState('networkidle');
  await shot('otp-error');

  // error page: invalid redirect uri
  await ctx.clearCookies();
  await page.goto(authUrl(locale, { redirect_uri: 'http://evil.invalid/cb' }));
  await page.waitForSelector('.br-card');
  await shot('error');

  // logout confirmation (signed in first)
  await ctx.clearCookies();
  await start();
  await fillLogin(ana);
  await page.waitForLoadState('networkidle');
  await page.goto(`${KC}/realms/${REALM}/protocol/openid-connect/logout?client_id=baby-routine-web&post_logout_redirect_uri=${encodeURIComponent('http://localhost:5190/')}&kc_locale=${locale}`);
  await page.waitForSelector('.br-card');
  await shot('logout-confirm');

  await ctx.close();
}

// The terms-and-conditions required action is disabled by default in a new realm.
await admin('PUT', '/authentication/required-actions/TERMS_AND_CONDITIONS', {
  alias: 'TERMS_AND_CONDITIONS',
  name: 'Terms and Conditions',
  providerId: 'TERMS_AND_CONDITIONS',
  enabled: true,
  defaultAction: false,
  priority: 20,
});

const browser = await chromium.launch();
try {
  for (const locale of LOCALES)
    for (const scheme of SCHEMES)
      for (const width of VIEWPORTS) {
        console.log(`${locale} ${scheme} ${width}`);
        await runCombo(browser, locale, scheme, width);
      }
} finally {
  await browser.close();
  for (const id of created) await admin('DELETE', `/users/${id}`).catch(() => {});
}
